package com.medtrack.warehouse.service; import com.medtrack.shared.exception.*; import com.medtrack.warehouse.dto.*; import com.medtrack.warehouse.entity.*; import com.medtrack.warehouse.repository.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class WarehouseService {private final WarehouseRepository warehouses;private final StorageLocationRepository locations;public WarehouseService(WarehouseRepository w,StorageLocationRepository l){warehouses=w;locations=l;}public WarehouseResponse create(WarehouseRequest r){if(warehouses.existsByCode(r.code()))throw new DomainException("DUPLICATE_WAREHOUSE_CODE","Warehouse code already exists");return WarehouseResponse.of(warehouses.save(new Warehouse(r.code(),r.name(),r.type(),r.address(),r.latitude(),r.longitude(),r.contactPhone(),r.status())));} @Transactional(readOnly=true) public Page<WarehouseResponse> list(Pageable p){return warehouses.findAll(p).map(WarehouseResponse::of);} @Transactional(readOnly=true) public WarehouseResponse get(UUID id){return WarehouseResponse.of(find(id));} public WarehouseResponse update(UUID id,WarehouseRequest r){Warehouse w=find(id);w.update(r.name(),r.type(),r.address(),r.latitude(),r.longitude(),r.contactPhone(),r.status());return WarehouseResponse.of(w);} public StorageLocationResponse addLocation(UUID id,StorageLocationRequest r){Warehouse w=find(id);if(locations.existsByWarehouse_IdAndBinCode(id,r.binCode()))throw new DomainException("DUPLICATE_BIN_CODE","Bin code already exists in this warehouse");return StorageLocationResponse.of(locations.save(new StorageLocation(w,r.zone(),r.rack(),r.shelf(),r.binCode())));} @Transactional(readOnly=true) public List<StorageLocationResponse> locations(UUID id){find(id);return locations.findByWarehouse_Id(id).stream().map(StorageLocationResponse::of).toList();} private Warehouse find(UUID id){return warehouses.findById(id).orElseThrow(()->new NotFoundException("Warehouse"));}}
